    "suggestions": [
      "为什么栈和队列被称为“操作受限的线性表”，而不是新的逻辑结构？",
      "顺序表与链表在缓存命中率上的差异如何影响实际运行时间？",
      "循环队列为什么要“牺牲一个单元”来区分队空和队满？",
      "KMP 算法相比暴力匹配，核心优化点在哪里？"
    ],
    "kb": [
      {
        "pattern": "ADT|抽象数据类型",
        "answer": "ADT = 数据对象 + 数据关系 + 基本操作，强调逻辑定义与具体实现分离。"
      },
      {
        "pattern": "线性结构|一对一|前驱|后继",
        "answer": "线性结构中除首元素外每个元素有唯一前驱，除尾元素外有唯一后继。"
      },
      {
        "pattern": "栈|LIFO|后进先出",
        "answer": "栈只允许在一端（栈顶）插入和删除，访问模式为 LIFO。"
      },
      {
        "pattern": "队列|FIFO|先进先出",
        "answer": "队列只允许在一端入队、另一端出队，访问模式为 FIFO。"
      },
      {
        "pattern": "顺序表|数组|随机访问",
        "answer": "顺序表用连续内存存储，支持 $O(1)$ 随机访问，但插入删除平均需要 $O(n)$ 移动。"
      },
      {
        "pattern": "链表|指针|动态分配",
        "answer": "链表通过指针链接离散节点，插入删除定位后 $O(1)$，但不支持随机访问，且有额外指针空间开销。"
      },
      {
        "pattern": "KMP|模式匹配|前缀函数",
        "answer": "KMP 利用已匹配前缀的最长相等真前缀与真后缀长度（next/pi 数组）避免主串指针回退。"
      }
    ]
  },
