          "id": "b2-1-modes",
          "type": "compare",
          "intent": "对比 LIFO、FIFO、随机访问三种访问模式的特征与典型操作",
          "size": "l"
        },
        {
          "id": "b2-2-restricted",
          "type": "callout",
          "intent": "栈和队列是操作受限的线性表，不是新的逻辑结构",
          "size": "s"
        },
        {
          "id": "b2-3-paradigm",
          "type": "statement",
          "intent": "逻辑结构决定可用算法范式：LIFO 对应回溯、FIFO 对应广度优先、随机访问对应分治与二分",
          "size": "m"
        }
      ]
